public int candy(int[] ratings) {
    int n = ratings.length;
    if (n <= 1) return n;
    int total = n;
    int up = 0, down = 0, peak = 0;
    for (int i = 1; i < n; i++) {
        if (ratings[i] > ratings[i - 1]) {
            up++;
            down = 0;
            peak = up;
            total += up;
        } else if (ratings[i] == ratings[i - 1]) {
            up = 0;
            down = 0;
            peak = 0;
        } else {
            up = 0;
            down++;
            total += down;
            if (peak >= down) {
                total--;
            }
        }
    }
    return total;
}

