def candy(self, ratings: list[int]) -> int:
    n = len(ratings)
    if n <= 1:
        return n
    total = n
    up = down = peak = 0
    for i in range(1, n):
        if ratings[i] > ratings[i - 1]:
            up += 1
            down = 0
            peak = up
            total += up
        elif ratings[i] == ratings[i - 1]:
            up = down = peak = 0
        else:
            up = 0
            down += 1
            total += down
            if peak >= down:
                total -= 1
    return total

